export const GUIDE_DEFAULT_TX_SUMMARY_MAP: Record<string, Partial<AptTxSummary> | undefined> = {
  ...CANONICAL_TX_SUMMARY_MAP,
  ...GUIDE_APT_TX_SUMMARY_SNAPSHOT,
};

/**
 * Builds a 100% real-data mini preview card item for a guide apartment complex
 * from the verified MOLIT `tx-summary.json` dataset.
 */
export function buildGuideAptMiniPreview(
  aptName: string,
  txMap: Record<string, Partial<AptTxSummary> | undefined> = GUIDE_DEFAULT_TX_SUMMARY_MAP
): GuideAptMiniPreviewItem | null {
  const trimmed = (aptName || '').trim();
  if (!trimmed) return null;

  const hasTxMapEntries = Boolean(txMap && Object.keys(txMap).length > 0);
  const canonicalSlug =
    (hasTxMapEntries
      ? resolveCanonicalAptSlug(trimmed, {
          txMap: txMap as Record<string, unknown>,
        })
      : '') ||
    resolveCanonicalAptSlug(trimmed, {
      txMap: GUIDE_DEFAULT_TX_SUMMARY_MAP as Record<string, unknown>,
    }) ||
    trimmed;

  const primary = txMap?.[canonicalSlug] ?? txMap?.[trimmed];
  const fallback =
    GUIDE_DEFAULT_TX_SUMMARY_MAP[canonicalSlug] ?? GUIDE_DEFAULT_TX_SUMMARY_MAP[trimmed];
  const s = primary !== undefined ? primary : fallback;
  if (!s) return null;

  const dong = (s.dong || '동탄').trim() || '동탄';
  const displayName =
    getGuideAptDisplayName(canonicalSlug, dong) || getGuideAptDisplayName(trimmed, dong);
  const zoneId = dongToZoneId(dong);
  const zoneInfo = getZoneById(zoneId);
  const zoneName = zoneInfo?.name || '동탄 권역';

  const latestPrice =
    typeof s.latestPrice === 'number' && Number.isFinite(s.latestPrice) && s.latestPrice > 0
      ? s.latestPrice
      : 0;
  const latestRent =
    typeof s.latestRentDeposit === 'number' &&
    Number.isFinite(s.latestRentDeposit) &&
    s.latestRentDeposit > 0
      ? s.latestRentDeposit
      : 0;
  const txCount =
    typeof s.txCount === 'number' && Number.isFinite(s.txCount) && s.txCount > 0
      ? Math.round(s.txCount)
      : 0;

  if (latestPrice <= 0 && latestRent <= 0 && txCount <= 0) {
    return null;
  }

  const rawPriceEok = typeof s.latestPriceEok === 'string' ? s.latestPriceEok.trim() : '';
  const latestPriceStr =
    latestPrice > 0
      ? rawPriceEok && rawPriceEok !== '0' && rawPriceEok !== '0만'
        ? rawPriceEok
        : formatPriceEok(latestPrice)
      : '정보 없음';

  const rawRentEok =
    typeof s.latestRentDepositEok === 'string' ? s.latestRentDepositEok.trim() : '';
  const latestRentStr =
    latestRent > 0
      ? rawRentEok && rawRentEok !== '0' && rawRentEok !== '0만'
        ? rawRentEok
        : formatPriceEok(latestRent)
      : '정보 없음';

  const salesBase =
    (typeof s.avg1MPrice === 'number' && s.avg1MPrice > 0 ? s.avg1MPrice : 0) ||
    (typeof s.avg3MPrice === 'number' && s.avg3MPrice > 0 ? s.avg3MPrice : 0) ||
    latestPrice;
  const rentBase =
    (typeof s.avg1MRentDeposit === 'number' && s.avg1MRentDeposit > 0
      ? s.avg1MRentDeposit
      : 0) ||
    (typeof s.avg3MRentDeposit === 'number' && s.avg3MRentDeposit > 0
      ? s.avg3MRentDeposit
      : 0) ||
    latestRent;

  const rawRatio =
    salesBase > 0 && rentBase > 0 ? Math.round((rentBase / salesBase) * 100) : 0;
  const jeonseRatio = rawRatio > 0 && rawRatio <= 100 ? rawRatio : 0;

  const rawPer = salesBase > 0 && rentBase > 0 ? salesBase / rentBase : 0;
  const perValue =
    jeonseRatio > 0 && rawPer >= 1 && rawPer <= 10 ? rawPer.toFixed(2) : null;

  const latestDate = formatGuideTxDate(s.latestDate);
  const latestArea =
    typeof s.latestArea === 'number' && Number.isFinite(s.latestArea) && s.latestArea > 0
      ? Math.round(s.latestArea * 10) / 10
      : 0;
  const latestFloor =
    typeof s.latestFloor === 'number' && Number.isFinite(s.latestFloor) && s.latestFloor > 0
      ? Math.round(s.latestFloor)
      : 0;

  return {
    name: trimmed,
    displayName,
    canonicalSlug,
    href: `/apartment/${encodeURIComponent(canonicalSlug)}`,
    dong,
    zoneId,
    zoneName,
    latestPrice,
    latestPriceStr,
    latestRent,
    latestRentStr,
    jeonseRatio,
    perValue,
    latestDate,
    latestArea,
    latestFloor,
    txCount,
  };
}

export interface ResolvedGuideZoneSectionPreview {
  sectionHeadingMatch: string;
  sectionTitle: string;
  zoneId?: string;
  zoneName?: string;
  items: GuideAptMiniPreviewItem[];
}

/**
 * Resolves all configured `zoneSectionPreviews` for a guide article into real-data mini preview card lists.
 */
export function resolveGuideZoneSectionPreviews(
  article: GuideArticle,
  txMap: Record<string, Partial<AptTxSummary> | undefined> = GUIDE_DEFAULT_TX_SUMMARY_MAP
): ResolvedGuideZoneSectionPreview[] {
  const configs = article.zoneSectionPreviews || [];
  return configs
    .map((cfg) => {
      const items = cfg.apartments
        .map((aptName) => buildGuideAptMiniPreview(aptName, txMap))
        .filter((item): item is GuideAptMiniPreviewItem => item !== null);
      const zoneInfo = cfg.zoneId ? getZoneById(cfg.zoneId) : undefined;
      return {
        sectionHeadingMatch: cfg.sectionHeadingMatch,
        sectionTitle: cfg.sectionTitle,
        zoneId: cfg.zoneId,
        zoneName: zoneInfo?.name,
        items,
      };
    })
    .filter((section) => section.items.length > 0);
}

/**
 * Normalizes apartment complex display names and tx-summary keys into a canonical lookup token
 * so spaced UI aliases (e.g. '동탄역 시범 리슈빌', '예당마을 우미린 제일풍경채') resolve deterministically
 * to their exact guide entries without false substring collisions.
 */
export function normalizeGuideAptName(rawName: string | undefined): string {
  if (!rawName) return '';
  let norm = rawName
    .toLowerCase()
    .replace(/\s+/g, '')
    .replace(/\((?:목동|능동|반송동|청계동|여울동|오산동|영천동|석우동|장지동|송동|산척동|신동)\)$/g, '')
    .replace(/[()]/g, '')
    .replace(/아파트$/g, '')
    .replace(/^e편한세상/, '이편한세상');

  if (norm === '동탄역시범더샵센트럴시티' || norm === '시범포스코더샵') norm = '더샵센트럴시티';
  else if (norm === '동탄역시범반도유보라아이비파크4.0') norm = '시범반도유보라아이비파크4.0';
  else if (norm === '동탄역센트럴자이') norm = '동탄역센트럴자이a-10';
  else if (norm === '능동역이지더원') norm = '능동마을이지더원';
  else if (norm === '시범리슈빌') norm = '동탄역시범리슈빌';
  else if (norm === '시범우남' || norm === '시범우남퍼스트빌') norm = '동탄역시범우남퍼스트빌';
  else if (
    norm === '시범한화' ||
    norm === '시범한화꿈에그린' ||
    norm === '시범한화꿈에그린프레스티지'
  ) {
    norm = '동탄역시범한화꿈에그린프레스티지';
  } else if (norm === '예미지시그너스') norm = '동탄역예미지시그너스';
  else if (norm === '석우롯데캐슬' || norm === '석우동롯데캐슬') norm = '롯데캐슬';
  else if (norm.startsWith('예당마을') && norm.length > 4) norm = norm.slice(4);
  else if (norm.startsWith('동탄푸른마을')) norm = norm.slice(2);

  return norm;
}

export interface RelatedGuidesResult {
  relatedGuides: GuideArticle[];
  directGuides: GuideArticle[];
  hasDirectMatch: boolean;
  zone?: ZoneInfo;
}

interface PreindexedGuideArticle {
  article: GuideArticle;
  headToHeadNormKeys: Set<string>;
  featuredAptNormKeys: Set<string>;
}

let preindexedGuidesCache: PreindexedGuideArticle[] | null = null;
const relatedGuidesMemoCache = new Map<string, RelatedGuidesResult>();

function getPreindexedGuides(): PreindexedGuideArticle[] {
  if (preindexedGuidesCache) return preindexedGuidesCache;
  preindexedGuidesCache = GUIDE_ARTICLES.map((article) => {
    const headToHeadNormKeys = new Set<string>();
    for (const m of article.headToHeadComparisons || []) {
      const leftNorm = normalizeGuideAptName(m.leftApt);
      const rightNorm = normalizeGuideAptName(m.rightApt);
      if (leftNorm) headToHeadNormKeys.add(leftNorm);
      if (rightNorm) headToHeadNormKeys.add(rightNorm);
    }
    const featuredAptNormKeys = new Set<string>();
    for (const k of article.featuredApartments || []) {
      const kNorm = normalizeGuideAptName(k);
      if (kNorm) featuredAptNormKeys.add(kNorm);
    }
    return {
      article,
      headToHeadNormKeys,
      featuredAptNormKeys,
    };
  });
  return preindexedGuidesCache;
}

/**
 * Resolves comparison guides directly featuring an apartment (1:1 headToHeadComparisons prioritized first,
 * followed by featuredApartments), padding up to `minPadCount` with zone-level guides only when `dong` is
 * a verified Dongtan legal/administrative dong (preventing ghost slugs from leaking 'gbcx' fallback links).
 */
export function getRelatedGuidesForApartment(params: {
  aptName?: string;
  resolvedTxKey?: string;
  dong?: string;
  minPadCount?: number;
  maxTotal?: number;
}): RelatedGuidesResult {
  const { aptName, resolvedTxKey, dong, minPadCount = 3, maxTotal } = params;
  const cacheKey = `${aptName || ''}|${resolvedTxKey || ''}|${dong || ''}|${minPadCount}|${maxTotal ?? ''}`;
  const cachedResult = relatedGuidesMemoCache.get(cacheKey);
  if (cachedResult) return cachedResult;

  const trimmedDong = (dong || '').trim();
  const hasValidDong = KNOWN_DONGTAN_DONGS.has(trimmedDong);
  const normalizedDong = trimmedDong === '오산동' ? '여울동' : trimmedDong;
  const zoneId = hasValidDong ? dongToZoneId(normalizedDong) : undefined;
  const zone = zoneId ? getZoneById(zoneId) : undefined;

  const candidateNorms = new Set(
    [normalizeGuideAptName(aptName), normalizeGuideAptName(resolvedTxKey)].filter(
      (n) => n.length >= 3
    )
  );

  const matchesPreindexedSet = (normSet: Set<string>): boolean => {
    for (const cand of candidateNorms) {
      if (!normSet.has(cand)) continue;
      if (cand === '롯데캐슬' && hasValidDong && normalizedDong !== '석우동') {
        continue;
      }
      return true;
    }
    return false;
  };

  const preindexed = getPreindexedGuides();
  const headToHeadMatchedSlugs = new Set<string>();
  const directArticles: GuideArticle[] = [];

  for (const entry of preindexed) {
    const isH2H = matchesPreindexedSet(entry.headToHeadNormKeys);
    const isFeatured = isH2H || matchesPreindexedSet(entry.featuredAptNormKeys);
    if (isH2H) {
      headToHeadMatchedSlugs.add(entry.article.slug);
    }
    if (isFeatured) {
      directArticles.push(entry.article);
    }
  }

  const directGuides = directArticles.sort((a, b) => {
    const scoreDiff =
      Number(headToHeadMatchedSlugs.has(b.slug)) - Number(headToHeadMatchedSlugs.has(a.slug));
    if (scoreDiff !== 0) return scoreDiff;
    if (zoneId) {
      const zoneMatchDiff =
        Number((b.featuredZones || []).includes(zoneId)) -
        Number((a.featuredZones || []).includes(zoneId));
      if (zoneMatchDiff !== 0) return zoneMatchDiff;
    }
    const specificityDiff =
      (a.featuredZones?.length || 99) - (b.featuredZones?.length || 99);
    if (specificityDiff !== 0) return specificityDiff;
    const updatedDiff = (b.updatedDate || b.date || '').localeCompare(
      a.updatedDate || a.date || ''
    );
    if (updatedDiff !== 0) return updatedDiff;
    return (b.date || '').localeCompare(a.date || '');
  });

  const directSlugSet = new Set(directGuides.map((d) => d.slug));
  const zoneGuides = zoneId
    ? GUIDE_ARTICLES.filter(
        (a) =>
          (a.featuredZones || []).includes(zoneId) &&
          !directSlugSet.has(a.slug)
      ).sort((a, b) => {
        const specificityDiff =
          (a.featuredZones?.length || 99) - (b.featuredZones?.length || 99);
        if (specificityDiff !== 0) return specificityDiff;
        const updatedDiff = (b.updatedDate || b.date || '').localeCompare(
          a.updatedDate || a.date || ''
        );
        if (updatedDiff !== 0) return updatedDiff;
        return (b.date || '').localeCompare(a.date || '');
      })
    : [];

  const combined = [
    ...directGuides,
    ...zoneGuides.slice(0, Math.max(0, minPadCount - directGuides.length)),
  ];

  const relatedGuides =
    typeof maxTotal === 'number' && maxTotal > 0 ? combined.slice(0, maxTotal) : combined;

  const result: RelatedGuidesResult = {
    relatedGuides,
    directGuides,
    hasDirectMatch: directGuides.length > 0,
    zone,
  };
  if (relatedGuidesMemoCache.size >= 500) {
    const oldestKey = relatedGuidesMemoCache.keys().next().value;
    if (oldestKey !== undefined) {
      relatedGuidesMemoCache.delete(oldestKey);
    }
  }
  relatedGuidesMemoCache.set(cacheKey, result);
  return result;
}

export function buildGuideArticleJsonLd(
  article: GuideArticle,
  baseUrl = 'https://dongtanview.com'
) {
  const currentUrl = `${baseUrl}/guide/${article.slug}`;
  const mentions = (article.featuredApartments || []).map((aptName) => {
    const canonicalSlug = resolveCanonicalAptSlug(aptName) || aptName;
    const displayName = getGuideAptDisplayName(canonicalSlug);
    return {
      '@type': 'ApartmentComplex',
      name: displayName,
      alternateName: displayName !== canonicalSlug ? canonicalSlug : undefined,
      url: `${baseUrl}/apartment/${encodeURIComponent(canonicalSlug)}`,
    };
  });

  const articleNode: Record<string, unknown> = {
    '@type': 'Article',
    '@id': `${currentUrl}#article`,
    headline: article.title,
    alternativeHeadline: article.seoTitle || article.subtitle,
    description: article.seoDescription || article.description,
    datePublished: article.date,
    dateModified: article.updatedDate || article.date,
    author: {
      '@type': 'Organization',
      name: article.author,
      url: baseUrl,
    },
    publisher: {
      '@type': 'Organization',
      name: 'D-VIEW 부동산 데이터 랩스',
      url: baseUrl,
    },
    mainEntityOfPage: {
      '@type': 'WebPage',
      '@id': currentUrl,
    },
    keywords: article.tags.join(','),
  };

  if (mentions.length > 0) {
    articleNode.mentions = mentions;
  }

  const graph: Array<Record<string, unknown>> = [
    articleNode,
    {
      '@type': 'BreadcrumbList',
      '@id': `${currentUrl}#breadcrumb`,
      itemListElement: [
        {
          '@type': 'ListItem',
          position: 1,
          name: '홈',
          item: baseUrl,
        },
        {
          '@type': 'ListItem',
          position: 2,
          name: '동탄 부동산 가이드',
          item: `${baseUrl}/guide`,
        },
        {
          '@type': 'ListItem',
          position: 3,
          name: article.title,
          item: currentUrl,
        },
      ],
    },
  ];

  if (article.faqs && article.faqs.length > 0) {
    graph.push({
      '@type': 'FAQPage',
      '@id': `${currentUrl}#faq`,
      mainEntity: article.faqs.map((faq) => ({
        '@type': 'Question',
        name: faq.question,
        acceptedAnswer: {
          '@type': 'Answer',
          text: faq.answer,
        },
      })),
    });
  }

  return {
    '@context': 'https://schema.org',
    '@graph': graph,
  };
}

